<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/theme.php';
function portalH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='client'||!isset($user['client_id'],$user['id'])){header('Location: ./');exit;}
$db=coachingDatabase();$clientId=(int)$user['client_id'];$portalId=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}$action=(string)($_POST['action']??'');
if($action==='password'){$old=(string)($_POST['aktuelles_passwort']??'');$new=(string)($_POST['neues_passwort']??'');$q=$db->prepare('SELECT passwort_hash FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client AND aktiv=1');$q->execute(['id'=>$portalId,'client'=>$clientId]);$hash=$q->fetchColumn();if(!is_string($hash)||!password_verify($old,$hash))$error='Das aktuelle Passwort ist nicht korrekt.';elseif(strlen($new)<8||strlen($new)>4096)$error='Das neue Passwort muss mindestens 8 Zeichen haben.';else{$q=$db->prepare('UPDATE coaching_portal_zugaenge SET passwort_hash=:hash WHERE id=:id AND klient_id=:client');$q->execute(['hash'=>password_hash($new,PASSWORD_DEFAULT),'id'=>$portalId,'client'=>$clientId]);$notice='Passwort geändert.';}}
if($action==='task'){$id=(int)($_POST['task_id']??0);$status=(string)($_POST['status']??'');if(in_array($status,['offen','in_bearbeitung','erledigt'],true)){$q=$db->prepare('UPDATE coaching_aufgaben SET status=:status WHERE id=:id AND klient_id=:client AND klient_sichtbar=1');$q->execute(['status'=>$status,'id'=>$id,'client'=>$clientId]);$notice='Aufgabe aktualisiert.';}}
}
$q=$db->prepare('SELECT id,vorname,nachname,benutzer_id FROM klienten WHERE id=:id');$q->execute(['id'=>$clientId]);$client=$q->fetch(PDO::FETCH_ASSOC);if(!$client){http_response_code(404);exit('Klient nicht gefunden.');}$themeCss=coachingThemeCss($db,(int)$client['benutzer_id']);
$q=$db->prepare('SELECT beginn,dauer_minuten,format,status FROM termine WHERE klient_id=:client ORDER BY beginn DESC LIMIT 50');$q->execute(['client'=>$clientId]);$appointments=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT titel,beschreibung,erfolgskriterium,zieltermin,status FROM coaching_ziele WHERE klient_id=:client AND coach_benutzer_id=:coach ORDER BY geaendert_am DESC LIMIT 100');$q->execute(['client'=>$clientId,'coach'=>(int)$client['benutzer_id']]);$goals=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT id,titel,beschreibung,faellig_am,status FROM coaching_aufgaben WHERE klient_id=:client AND coach_benutzer_id=:coach AND klient_sichtbar=1 ORDER BY (status=\'erledigt\'),faellig_am IS NULL,faellig_am LIMIT 100');$q->execute(['client'=>$clientId,'coach'=>(int)$client['benutzer_id']]);$tasks=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare("SELECT id,titel,vorlage_version,status,zugewiesen_am FROM coaching_klientendokumente WHERE klient_id=:client AND status IN ('zugewiesen','ausgegeben','zurueckgekommen') ORDER BY zugewiesen_am DESC LIMIT 100");$q->execute(['client'=>$clientId]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);$files=[];$fq=$db->prepare('SELECT f.id,f.klientendokument_id,f.version,f.originalname FROM coaching_dokumentdateien f INNER JOIN coaching_klientendokumente d ON d.id=f.klientendokument_id WHERE d.klient_id=:client AND d.status IN (\'zugewiesen\',\'ausgegeben\',\'zurueckgekommen\') ORDER BY f.hochgeladen_am DESC');$fq->execute(['client'=>$clientId]);foreach($fq->fetchAll(PDO::FETCH_ASSOC) as $f)$files[(int)$f['klientendokument_id']][]=$f;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mein Coaching</title><link rel="stylesheet" href="assets/layout.css"><style>body.portal{display:block;background:#f5f7f5}.portal-wrap{max-width:1100px;margin:auto;padding:24px 18px 60px}.portal-head,.card{background:white;border:1px solid #e4ebe6;border-radius:15px;padding:20px;margin:15px 0}.portal-head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.portal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.row{border-top:1px solid #edf1ee;padding:12px 0}.muted{color:#718078;font-size:13px}.form{display:flex;gap:8px;flex-wrap:wrap}.form input,.form select{padding:9px;border:1px solid #dce5df;border-radius:8px}.button{background:#245c50;color:white;border:0;border-radius:8px;padding:9px 12px}.notice{background:#edf5ef;padding:12px}.error{background:#fff3f1;padding:12px}@media(max-width:700px){.portal-grid{grid-template-columns:1fr}}</style><style><?= $themeCss ?></style></head><body class="portal"><main class="portal-wrap"><header class="portal-head"><div><strong>Mein Coaching</strong><div class="muted"><?=portalH($client['vorname'].' '.$client['nachname'])?></div></div><form method="post" action="./"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><button class="button">Abmelden</button></form></header><?php if($notice):?><p class="notice"><?=portalH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=portalH($error)?></p><?php endif;?>
<div class="portal-grid"><section class="card"><h2>Termine</h2><?php if(!$appointments):?><p class="muted">Noch keine Termine.</p><?php else:foreach($appointments as $a):?><div class="row"><strong><?=portalH(date('d.m.Y · H:i',strtotime($a['beginn'])))?></strong><div class="muted"><?=portalH($a['format'].' · '.$a['dauer_minuten'].' Minuten · '.$a['status'])?></div></div><?php endforeach;endif;?></section>
<section class="card"><h2>Meine Ziele</h2><?php if(!$goals):?><p class="muted">Noch keine Ziele freigegeben.</p><?php else:foreach($goals as $g):?><div class="row"><strong><?=portalH($g['titel'])?> · <?=portalH($g['status'])?></strong><div class="muted"><?=portalH($g['beschreibung']??'')?><?= $g['zieltermin']?' · Zieltermin '.portalH(date('d.m.Y',strtotime($g['zieltermin']))):''?></div></div><?php endforeach;endif;?></section>
<section class="card"><h2>Aufgaben und Übungen</h2><?php if(!$tasks):?><p class="muted">Keine offenen Aufgaben.</p><?php else:foreach($tasks as $t):?><div class="row"><strong><?=portalH($t['titel'])?></strong><div class="muted"><?=portalH($t['beschreibung']??'')?><?= $t['faellig_am']?' · Fällig '.portalH(date('d.m.Y',strtotime($t['faellig_am']))):''?></div><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="task"><input type="hidden" name="task_id" value="<?=(int)$t['id']?>"><select name="status"><option value="offen" <?=$t['status']==='offen'?'selected':''?>>Offen</option><option value="in_bearbeitung" <?=$t['status']==='in_bearbeitung'?'selected':''?>>In Bearbeitung</option><option value="erledigt" <?=$t['status']==='erledigt'?'selected':''?>>Erledigt</option></select><button class="button">Speichern</button></form></div><?php endforeach;endif;?></section>
<section class="card"><h2>Dokumente</h2><?php if(!$docs):?><p class="muted">Keine Dokumente bereitgestellt.</p><?php else:foreach($docs as $d):?><div class="row"><strong><?=portalH($d['titel'])?> · <?=portalH($d['status'])?></strong><div class="muted"><a href="document-download.php?type=assigned-template&amp;id=<?=(int)$d['id']?>">Dokument öffnen</a></div><?php foreach($files[(int)$d['id']]??[] as $f):?><div class="muted">Unterschriebene Fassung v<?=(int)$f['version']?> · <?=portalH($f['originalname'])?> · <a href="document-download.php?type=return&amp;id=<?=(int)$f['id']?>">Öffnen</a></div><?php endforeach;?></div><?php endforeach;endif;?></section>
<section class="card"><h2>Passwort ändern</h2><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="password"><input type="password" name="aktuelles_passwort" placeholder="Aktuelles Passwort" required><input type="password" name="neues_passwort" placeholder="Neues Passwort (mind. 8 Zeichen)" minlength="8" required><button class="button">Ändern</button></form></section></div></main></body></html>